        { q: "He's highly ___ to change his mind at this stage. (маловероятно)", a: ["unlikely", "impossible", "improbably"], c: 0 }, { q: "There's every ___ that the book will become a classic.", a: ["chance", "probability of", "likely"], c: 0 },
        { q: "Camus is ___ the most widely read philosopher of the absurd. (можно утверждать)", a: ["arguably", "supposedly", "doubtfully"], c: 0 }, { q: "It stands to ___ that a life without purpose feels empty.", a: ["reason", "logic", "sense"], c: 0 },
        { q: "She will ___ never find the answer she's looking for.", a: ["probably", "likely to", "possibly to"], c: 0 }, { q: "There's little ___ of a definitive answer. (мало шансов)", a: ["chance", "possible", "probable"], c: 0 }
